function setColor(value){root.style.setProperty('--nexora-header-color',value);header.style.background='linear-gradient(105deg,'+value+',color-mix(in srgb,'+value+' 70%,#56a9df))';localStorage.setItem('nexora-allure-header',value);colors.forEach(button=>button.classList.toggle('active',button.dataset.headerColor===value))}
