  return `<article class="coverage-suite" id="suite-${group.key}" style="--suite-color:${group.color}"><button type="button" class="suite-heading" data-filter-suite="${group.key}" aria-label="Show ${group.total} ${group.name} test cases"><span class="suite-icon">◈</span><span class="suite-name"><strong>${group.name}</strong><small>${group.description}</small></span><b class="suite-total">${group.total}</b></button><div class="suite-rate">${group.total ? Math.round((group.passed / group.total) * 100) : 0}% passed</div>${bar('Passed', group.passed, 'passed', 'passed')}${bar('Failed / broken', group.failed, 'failed', 'failed')}${bar('Skipped', group.skipped, 'skipped', 'skipped')}</article>`;
